// JUDGE · C21 (playable with missing assets), C23 (textures with the manifest's sizes) and C23b (an asset served with
// other sizes is shown at the manifest's size, game still completable), per `_dummy` variant, each with its own manifest
// and assetBase. Assets "present" are generated by the test and served with route.fulfill (real files from the
// browser's encoder, exact sizes; horizontal strip for spritesheets). Texture data comes from handle.debugTextures().
// "Completed with the keyboard": the single-phase game with Enter/arrows; run games at ×10 and the review by keyboard.
import fs from "node:fs";
import path from "node:path";
import type { Page } from "@playwright/test";
import {
  ALL_VARIANTS,
  allPresent,
  expect,
  fastParams,
  finishGame,
  gotoBench,
  readManifest,
  realParams,
  serveAssets,
  startGame,
  test,
  watchConsole,
  type AssetPlan,
  type ConformanceWindow,
  type DebugTexture,
  type ManifestEntry,
  type Variant,
} from "./support";

function debugTextures(page: Page): Promise<DebugTexture[] | string> {
  return page.evaluate(() => {
    const h = (window as unknown as ConformanceWindow).__conformance.handle();
    if (!h) return "sin handle";
    if (typeof h.debugTextures !== "function") return "el handle no expone debugTextures() con testHooks";
    return JSON.parse(JSON.stringify(h.debugTextures())) as DebugTexture[];
  });
}

const framesOf = (e: ManifestEntry) => e.frames?.count ?? 1;

async function playThrough(page: Page, variant: Variant, plan: AssetPlan, manifest: ManifestEntry[], params = fastParams(variant)) {
  const c = watchConsole(page, variant.assetBase);
  await serveAssets(page, plan, page, manifest, variant.assetBase);
  await gotoBench(page, variant.id, params);
  await startGame(page);
  return c;
}

const manifestExists = (v: Variant) => fs.existsSync(path.join(process.env.JUDGE_MODULES_ROOT ?? process.cwd(), v.dir, "assets.manifest.json"));

for (const v of ALL_VARIANTS) {
  test.describe(`${v.id}`, () => {
    test.skip(({ variant }) => variant.id !== v.id, "corre en el proyecto de su variante");
    if (!manifestExists(v)) {
      test(`C21–C23b · ${v.dir}/assets.manifest.json existe`, () => {
        expect(manifestExists(v), `falta ${v.dir}/assets.manifest.json`).toBe(true);
      });
      return;
    }
    const manifest = readManifest(v.dir);

    test("C21(a) · con todas las rutas de assetBase en 404 llega a onReady y se completa con teclado", async ({ page, variant }) => {
      const c = await playThrough(page, variant, {}, manifest);
      await finishGame(page, variant);
      expect.soft(c.pageErrors, "pageerror").toEqual([]);
      expect.soft(c.errors(), "console.error (sin los 404 de assetBase)").toEqual([]);
    });

    for (const missing of manifest) {
      test(`C21(b) · solo ${missing.file} en 404 (el resto presente): llega a onReady y se completa con teclado`, async ({ page, variant }) => {
        const c = await playThrough(page, variant, { ...allPresent(manifest), [missing.file]: "404" }, manifest);
        await finishGame(page, variant);
        expect.soft(c.pageErrors, "pageerror").toEqual([]);
        expect.soft(c.errors(), "console.error (sin los 404 de assetBase)").toEqual([]);
      });
    }

    for (const condition of ["faltantes", "presentes"] as const) {
      test(`C23 · texturas con las medidas y frames del manifiesto, assets ${condition}`, async ({ page, variant }) => {
        // ×1: the textures are read while the run is still alive.
        await playThrough(page, variant, condition === "faltantes" ? {} : allPresent(manifest), manifest, realParams());
        const textures = await debugTextures(page);
        expect(Array.isArray(textures), String(textures)).toBe(true);
        const list = textures as DebugTexture[];
        test.info().annotations.push({ type: "info", description: `debugTextures(): ${JSON.stringify(list)}` });
        for (const entry of manifest) {
          const t = list.find((x) => x.key === entry.key);
          expect.soft(t, `textura "${entry.key}"`).toBeDefined();
          if (!t) continue;
          expect.soft({ width: t.width, height: t.height, frames: t.frames }, `medidas de "${entry.key}"`).toEqual({
            width: entry.width,
            height: entry.height,
            frames: framesOf(entry),
          });
          // Agreed in the ticket: present → "file" (the served file is really used), missing → "placeholder".
          expect.soft(t.source, `source de "${entry.key}"`).toBe(condition === "presentes" ? "file" : "placeholder");
        }
      });
    }

    for (const odd of manifest) {
      test(`C23b · ${odd.file} servido con otras medidas se muestra con las del manifiesto y el juego se completa`, async ({ page, variant }) => {
        const plan: AssetPlan = { ...allPresent(manifest), [odd.file]: { width: odd.width * 2, height: odd.height } };
        const c = await playThrough(page, variant, plan, manifest);
        const textures = await debugTextures(page);
        expect(Array.isArray(textures), String(textures)).toBe(true);
        const t = (textures as DebugTexture[]).find((x) => x.key === odd.key);
        test.info().annotations.push({ type: "info", description: `debugTextures("${odd.key}"): ${JSON.stringify(t)}` });
        expect.soft(t, `textura "${odd.key}"`).toBeDefined();
        if (t) {
          expect.soft({ width: t.width, height: t.height, frames: t.frames }, `medida mostrada de "${odd.key}"`).toEqual({
            width: odd.width,
            height: odd.height,
            frames: framesOf(odd),
          });
          // Agreed in the ticket: a file with other sizes is redrawn at the manifest's → "scaled".
          expect.soft(t.source, `source de "${odd.key}"`).toBe("scaled");
        }
        await finishGame(page, variant);
        expect.soft(c.pageErrors, "pageerror").toEqual([]);
      });
    }
  });
}
